// flush POSTs one batch as OTLP/JSON. The body shape matches the
// OTel collector's expected JSON envelope (resourceSpans[] /
// scopeSpans[] / spans[]). On error the batch is dropped — the
// run loop logs the failure and moves on.
func (e *Exporter) flush(batch []*Span) error {
	if len(batch) == 0 {
		return nil
	}
	body, err := buildOTLPJSON(batch)
	if err != nil {
		return fmt.Errorf("tracing: marshal: %w", err)
	}
	ctx, cancel := context.WithTimeout(context.Background(), e.timeout)
	defer cancel()

	var lastErr error
	for attempt := 0; attempt <= maxRetries; attempt++ {
		if attempt > 0 {
			delay := retryBaseDelay * time.Duration(1<<(attempt-1))
			if delay > maxRetryDelay {
				delay = maxRetryDelay
			}
			select {
			case <-ctx.Done():
				return lastErr // return most recent error, not ctx.Err()
			case <-time.After(delay):
			}
		}

		req, err := http.NewRequestWithContext(ctx, http.MethodPost, e.endpoint, bytes.NewReader(body))
		if err != nil {
			return fmt.Errorf("tracing: build request: %w", err)
		}
		req.Header.Set("Content-Type", "application/json")
		resp, err := e.client.Do(req)
		if err != nil {
			lastErr = fmt.Errorf("tracing: do: %w", err)
			// Do not retry on network errors — they indicate a persistent
			// problem (unreachable host, TLS handshake failure, etc.) and
			// the next attempt will likely fail the same way.
			break
		}
		if resp != nil {
			defer resp.Body.Close()
		}
		if resp.StatusCode >= 400 {
			lastErr = fmt.Errorf("tracing: collector status %d", resp.StatusCode)
			// 4xx: non-retryable client errors — fail immediately
			if resp.StatusCode < 500 {
				return lastErr
			}
			// 5xx: retryable collector errors
			if attempt < maxRetries {
				continue
			}
			break // retries exhausted
		}
		return nil // success
	}
	return lastErr
}

