// treats a nil Tracer as "tracing disabled", which preserves the
// pre-issue-#41 behaviour exactly when the operator leaves
// NEXUS_TRACING_ENDPOINT empty.
type Exporter struct {
	endpoint string
	client   *http.Client
	timeout  time.Duration

